"""The "Generated by GNOST" line added to the Markdown files GNOST writes.

`Footer` builds that line (it can be switched off with `footer = false` in `.gnost.toml`) and
appends it to a document. The "try it" command fits the project's main language, so a Java
team sees Maven and a JavaScript team sees npx. Add a language to `TRY_COMMANDS` to teach it.
"""

from __future__ import annotations

from typing import Dict, Mapping, Optional, Tuple

from gnost import __version__

HOME_URL = "https://gnost.readthedocs.io"
DEFAULT_COMMAND = "npx gnost-cli onboard ."
# language name (as the scanner reports it) -> how that ecosystem runs GNOST
TRY_COMMANDS: Dict[str, str] = {
    "python": "uvx gnost onboard .",
    "java": "mvn io.github.mohdzain98:gnost-maven-plugin:onboard",
    "javascript": "npx gnost-cli onboard .",
    "typescript": "npx gnost-cli onboard .",
}


class Footer:
    """One footer line; empty when disabled."""

    def __init__(
        self,
        enabled: bool = True,
        version: str = __version__,
        command: str = DEFAULT_COMMAND,
    ) -> None:
        self.enabled = enabled
        self.version = version
        self.command = command

    def for_languages(self, languages: Optional[Mapping[str, int]]) -> "Footer":
        """A footer whose command fits the language with the most files."""
        known: Tuple[Tuple[str, int], ...] = tuple(
            (name, count)
            for name, count in (languages or {}).items()
            if name.lower() in TRY_COMMANDS
        )
        if not known:
            return self
        main = max(known, key=lambda item: item[1])[0].lower()
        return Footer(self.enabled, self.version, TRY_COMMANDS[main])

    def line(self) -> str:
        """The footer as one Markdown line, or an empty string when switched off."""
        if not self.enabled:
            return ""
        return (
            f"<sub>Generated by [GNOST]({HOME_URL}) {self.version}. "
            f"Try it on your own code: `{self.command}`</sub>"
        )

    def append(self, text: str) -> str:
        """The text followed by a rule and the footer; unchanged when disabled."""
        if not self.enabled:
            return text
        return text.rstrip("\n") + f"\n\n---\n\n{self.line()}\n"
